<div class="welcome-row"><div><h2>Входящие обращения</h2><p class="muted">Сообщения, отправленные через форму обратной связи.</p></div></div><div class="panel table-panel"><?php if (!$messages): ?><div class="empty-state"><strong>Обращений пока нет</strong></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Отправитель</th><th>Тема</th><th>Сообщение</th><th>Дата</th></tr></thead><tbody><?php foreach ($messages as $message): ?><tr><td><strong><?= e($message['name']) ?></strong><small class="table-sub"><?= e($message['email']) ?></small></td><td><?= e($message['topic']) ?></td><td><?= e($message['message']) ?></td><td><?= e(date('d.m.Y H:i',strtotime($message['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
